public class ObjectReader__findRootDeserializer_TriageGen1Test {

    private ObjectMapper mapper;
    private DeserializationContext ctxt;
    private JavaType javaType;
    private JsonDeserializer<Object> mockDeserializer;

    // Helper class to access protected method since it's in a different package or protected
    private static class TestableObjectReader extends ObjectReader {
        protected TestableObjectReader(ObjectMapper mapper, DeserializationConfig config) {
            super(mapper, config);
        }

        public JsonDeserializer<Object> publicFindRootDeserializer(DeserializationContext ctxt, JavaType valueType) 
                throws JsonMappingException {
            return _findRootDeserializer(ctxt, valueType);
        }
    }

    @Before
    public void setup() {
        mapper = new ObjectMapper();
        ctxt = mock(DeserializationContext.class);
        javaType = mock(JavaType.class);
        mockDeserializer = new StdDeserializer<Object>(Object.class) {};
    }

    /**
     * Tests that if _rootDeserializer is already set, it returns it immediately.
     */
    @Test
    public void testFindRootDeserializer_ReturnsExistingRootDeserializer() throws Exception {
        TestableObjectReader reader = new TestableObjectReader(mapper, mapper.getDeserializationConfig());

        // Use reflection to set the private/protected field _rootDeserializer
        Field rootDeserField = ObjectReader.class.getDeclaredField("_rootDeserializer");
        rootDeserField.setAccessible(true);
        rootDeserField.set(reader, mockDeserializer);

        JsonDeserializer<Object> result = reader.publicFindRootDeserializer(ctxt, javaType);

        assertEquals(mockDeserializer, result);
        verifyNoInteractions(ctxt);
    }

    /**
     * Tests that if valueType is null, it throws JsonMappingException.
     */
    @Test(expected = JsonMappingException.class)
    public void testFindRootDeserializer_ThrowsExceptionWhenTypeIsNull() throws JsonMappingException {
        TestableObjectReader reader = new TestableObjectReader(mapper, mapper.getDeserializationConfig());
        reader.publicFindRootDeserializer(ctxt, null);
    }

    /**
     * Tests that if the deserializer is already in the _rootDeserializers map, it returns it.
     */
    @Test
    public void testFindRootDeserializer_ReturnsFromCache() throws Exception {
        TestableObjectReader reader = new TestableObjectReader(mapper, mapper.getDeserializationConfig());

        // Setup the internal map _rootDeserializers
        Field cacheField = ObjectReader.class.getDeclaredField("_rootDeserializers");
        cacheField.setAccessible(true);
        Map<JavaType, JsonDeserializer<Object>> cache = new HashMap<>();
        cache.put(javaType, mockDeserializer);
        cacheField.set(reader, cache);

        JsonDeserializer<Object> result = reader.publicFindRootDeserializer(ctxt, javaType);

        assertEquals(mockDeserializer, result);
        verify(ctxt, never()).findRootValueDeserializer(any());
    }

    /**
     * Tests the happy path: type not in cache, found by provider, and added to cache.
     */
    @Test
    public void testFindRootDeserializer_ResolvesViaContextAndCaches() throws Exception {
        TestableObjectReader reader = new TestableObjectReader(mapper, mapper.getDeserializationConfig());

        // Ensure cache is empty
        Field cacheField = ObjectReader.class.getDeclaredField("_rootDeserializers");
        cacheField.setAccessible(true);
        Map<JavaType, JsonDeserializer<Object>> cache = new HashMap<>();
        cacheField.set(reader, cache);

        when(ctxt.findRootValueDeserializer(javaType)).thenReturn(mockDeserializer);

        JsonDeserializer<Object> result = reader.publicFindRootDeserializer(ctxt, javaType);

        assertEquals(mockDeserializer, result);
        verify(ctxt, times(1)).findRootValueDeserializer(javaType);
        // Verify it was cached
        assertEquals(mockDeserializer, cache.get(javaType));
    }

    /**
     * Tests that if the provider returns null, it throws JsonMappingException.
     */
    @Test
    public void testFindRootDeserializer_ThrowsExceptionWhenProviderReturnsNull() throws JsonMappingException {
        TestableObjectReader reader = new TestableObjectReader(mapper, mapper.getDeserializationConfig());

        Field cacheField = ObjectReader.class.getDeclaredField("_rootDeserializers");
        cacheField.setAccessible(true);
        cacheField.set(reader, new HashMap<JavaType, JsonDeserializer<Object>>());

        when(ctxt.findRootValueDeserializer(javaType)).thenReturn(null);

        try {
            reader.publicFindRootDeserializer(ctxt, javaType);
            org.junit.Assert.fail("Should have thrown JsonMappingException");
        } catch (JsonMappingException e) {
            org.junit.Assert.assertTrue(e.getMessage().contains("Can not find a deserializer"));
        }
    }
}
